-- IDEALO SV · Clientes 360
alter table public.clients add column if not exists client_code text, add column if not exists logo_url text, add column if not exists tags text[] default '{}', add column if not exists sales_owner text, add column if not exists commercial_status text default 'ACTIVE', add column if not exists preferred_channel text default 'WHATSAPP', add column if not exists credit_days integer default 0, add column if not exists blocked_for_debt boolean default false, add column if not exists latitude numeric, add column if not exists longitude numeric, add column if not exists delivery_address text, add column if not exists installation_address text, add column if not exists address_reference text, add column if not exists inactive_reason text, add column if not exists updated_at timestamptz default now();
create unique index if not exists clients_company_code_uq on public.clients(company_id,client_code) where client_code is not null;
create index if not exists clients_company_tax_idx on public.clients(company_id,tax_id); create index if not exists clients_company_nrc_idx on public.clients(company_id,nrc); create index if not exists clients_company_phone_idx on public.clients(company_id,phone);
create table if not exists public.client_contacts(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,client_id uuid not null references public.clients(id) on delete cascade,name text not null,position text,phone text,email text,is_primary boolean default false,created_at timestamptz default now());
create table if not exists public.client_addresses(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,client_id uuid not null references public.clients(id) on delete cascade,address_type text not null default 'DELIVERY',label text,department_code text,municipality_code text,district_code text,address text not null,reference text,latitude numeric,longitude numeric,is_primary boolean default false,created_at timestamptz default now());
create table if not exists public.client_activities(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,client_id uuid not null references public.clients(id) on delete cascade,activity_type text not null,title text not null,detail text,due_at timestamptz,completed_at timestamptz,created_by uuid default auth.uid(),created_at timestamptz default now());
alter table public.client_contacts enable row level security; alter table public.client_addresses enable row level security; alter table public.client_activities enable row level security;
do $$ declare t text; begin foreach t in array array['client_contacts','client_addresses','client_activities'] loop execute format('drop policy if exists company_member_access on public.%I',t); execute format('create policy company_member_access on public.%I for all to authenticated using (exists(select 1 from public.company_members m where m.company_id=%I.company_id and m.user_id=auth.uid())) with check (exists(select 1 from public.company_members m where m.company_id=%I.company_id and m.user_id=auth.uid()))',t,t,t); end loop; end $$;